import { FormsModule } from "@angular/forms";
import {
  ChangeDetectionStrategy,
  Component,
  inject,
  OnInit,
  signal,
} from "@angular/core";

import { ButtonModule } from "primeng/button";

import { User, userStore } from "src/app/store/userStore";
import { AdmUserService } from "src/app/administration/services/adm-user.service";

const primengModules = [ButtonModule];

type OperationType = "creating" | "updating" | "deleting" | null;

interface LoadingState {
  isLoading: boolean;
  operation?: OperationType;
}

@Component({
  selector: "app-main-dashboard",
  standalone: true,
  imports: [...primengModules, FormsModule],
  templateUrl: "./main-dashboard.component.html",
  styleUrl: "./main-dashboard.component.css",
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MainDashboardComponent implements OnInit {
  readonly userStore = inject(userStore);
  private userService = inject(AdmUserService);

  loadingStates = signal<{ [key: number]: LoadingState }>({});
  errorStates = signal<{ [key: number]: string | null }>({});

  ngOnInit() {
    this.userService.fetchUsers();
  }

  addUser() {
    const newUser: Omit<User, "token"> = {
      id: -1,
      firstName: "John",
      lastName: "Doe",
      username: "johndoe3",
      password: "password",
      createdAt: new Date().toISOString(),
    };
    this.userStore.addUser(newUser);
    // this.authService.register(newUser);
  }

  deleteUser(userId: number) {
    this.loadingStates.set({
      ...this.loadingStates(),
      [userId]: { isLoading: true, operation: "deleting" },
    });
    this.errorStates.set({ ...this.errorStates(), [userId]: null });

    this.userService.deleteUser(userId).subscribe({
      next: () => {
        this.userStore.removeUser(userId);
        this.loadingStates.set({
          ...this.loadingStates(),
          [userId]: { isLoading: false },
        });
      },
      error: (err) => {
        this.errorStates.set({ ...this.errorStates(), [userId]: err.message });
        this.loadingStates.set({
          ...this.loadingStates(),
          [userId]: { isLoading: false },
        });
      },
    });
  }

  updateUser(userId: number) {
    const updatedUser = {
      id: userId,
      username: "janeDoe",
      firstName: "Jane",
      lastName: "MDB",
      createdAt: new Date().toISOString(),
    };

    this.loadingStates.set({
      ...this.loadingStates(),
      [userId]: { isLoading: true, operation: "updating" },
    });
    this.errorStates.set({ ...this.errorStates(), [userId]: null });

    this.userService.updateUser(updatedUser).subscribe({
      next: () => {
        this.loadingStates.set({
          ...this.loadingStates(),
          [userId]: { isLoading: false },
        });
      },
      error: (err) => {
        this.errorStates.set({ ...this.errorStates(), [userId]: err.message });
        this.loadingStates.set({
          ...this.loadingStates(),
          [userId]: { isLoading: false },
        });
      },
    });
  }
}
```

Ayudame a refactirzar este componente, para que sea más fácil de leer y mantener. en especial el manejo de estados de carga y errores.
Claro, podemos refactorizar el componente para mejorar la legibilidad y el manejo de los estados de carga y errores. Aquí hay algunos pasos que podemos seguir:

1. **Crear un servicio para manejar los estados de carga y errores**: Esto ayudará a centralizar la lógica y hacer que el componente sea más limpio.
2. **Usar métodos auxiliares para actualizar los estados**: Esto reducirá la repetición de código.
3. **Separar la lógica de negocio en métodos más pequeños y específicos**: Esto hará que el código sea más modular y fácil de entender.

Vamos a implementar estos cambios:

### 1. Crear un servicio para manejar los estados de carga y errores

Primero, creamos un servicio llamado `LoadingErrorService`:

```ts
// src/app/services/loading-error.service.ts
import { Injectable } from '@angular/core';
import { signal } from '@angular/core';

type OperationType = "creating" | "updating" | "deleting" | null;

interface LoadingState {
  isLoading: boolean;
  operation?: OperationType;
}

@Injectable({
  providedIn: 'root',
})
export class LoadingErrorService {
  loadingStates = signal<{ [key: number]: LoadingState }>({});
  errorStates = signal<{ [key: number]: string | null }>({});

  setLoadingState(userId: number, state: LoadingState) {
    this.loadingStates.set({
      ...this.loadingStates(),
      [userId]: state,
    });
  }

  setErrorState(userId: number, error: string | null) {
    this.errorStates.set({
      ...this.errorStates(),
      [userId]: error,
    });
  }
}
```

